import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.BztkuPcJ.js";const h=JSON.parse('{"title":"Sección 3: Veredicto Retrospectivo de los Sub-Agentes","description":"","frontmatter":{},"headers":[],"relativePath":"journey/retrospective.md","filePath":"journey/retrospective.md"}'),i={name:"journey/retrospective.md"};function s(d,e,n,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="seccion-3-veredicto-retrospectivo-de-los-sub-agentes" tabindex="-1">Sección 3: Veredicto Retrospectivo de los Sub-Agentes <a class="header-anchor" href="#seccion-3-veredicto-retrospectivo-de-los-sub-agentes" aria-label="Permalink to &quot;Sección 3: Veredicto Retrospectivo de los Sub-Agentes&quot;">​</a></h1><p>Recuperamos el <a href="https://github.com/rox651/proyecto-ingenieria-software/blob/main/architecture-checkpoint.md" target="_blank" rel="noreferrer">Punto de Control Arquitectónico</a> de la Tarea 2 y lo evaluamos <strong>en retrospectiva</strong> tras completar los issues <code>#002–#009</code>.</p><hr><h2 id="recordatorio-tres-sub-agentes-paralelos" tabindex="-1">Recordatorio: tres sub-agentes paralelos <a class="header-anchor" href="#recordatorio-tres-sub-agentes-paralelos" aria-label="Permalink to &quot;Recordatorio: tres sub-agentes paralelos&quot;">​</a></h2><p>La skill <code>/improve-codebase-architecture</code> simuló tres propuestas para el módulo de composición:</p><table tabindex="0"><thead><tr><th>Agente</th><th>Propuesta</th><th>Idea central</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Factory minimalista</td><td><code>create_pipeline(mode)</code></td></tr><tr><td><strong>B</strong></td><td>Builder</td><td><code>PipelineBuilder().with_stt(...).build()</code></td></tr><tr><td><strong>C</strong></td><td>Registry/DI</td><td>Contenedor de providers nombrados</td></tr></tbody></table><p><strong>Híbrido elegido:</strong> Factory (A) + resolución por entorno + fallbacks en <code>_create_live_pipeline()</code>.</p><hr><h2 id="impacto-en-la-segunda-mitad-del-proyecto" tabindex="-1">Impacto en la segunda mitad del proyecto <a class="header-anchor" href="#impacto-en-la-segunda-mitad-del-proyecto" aria-label="Permalink to &quot;Impacto en la segunda mitad del proyecto&quot;">​</a></h2><h3 id="velocidad-de-desarrollo" tabindex="-1">Velocidad de desarrollo <a class="header-anchor" href="#velocidad-de-desarrollo" aria-label="Permalink to &quot;Velocidad de desarrollo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Métrica</th><th>Sin factory (proyectado)</th><th>Con factory (real)</th></tr></thead><tbody><tr><td>Archivos tocados por issue</td><td>3–4 (<code>api</code>, <code>cli</code>, <code>pipeline</code>, nuevo módulo)</td><td>1–2 (<code>factory</code>, nuevo módulo)</td></tr><tr><td>Regresiones en <code>/turn</code></td><td>Alta probabilidad</td><td>0 en 23 tests</td></tr><tr><td>Tiempo Ralph por issue</td><td>Re-wiring manual</td><td>Registrar en <code>_create_live_pipeline</code></td></tr></tbody></table><p>Issues <code>#004</code> TTS, <code>#005</code> playback, <code>#002</code> STT se integraron <strong>solo en factory</strong> — confirmando la predicción del checkpoint.</p><h3 id="debate-que-acelero-el-equipo" tabindex="-1">Debate que aceleró el equipo <a class="header-anchor" href="#debate-que-acelero-el-equipo" aria-label="Permalink to &quot;Debate que aceleró el equipo&quot;">​</a></h3><p>El sub-agente <strong>B (Builder)</strong> habría sido más explícito para tests parciales, pero el agente Ralph lo sobre-usaría (interfaces amplias = <strong>shallow modules</strong>). El sub-agente <strong>C (Registry)</strong> habría introducido indirección difícil de depurar en HITL.</p><p>La factory ganó por <strong>profundidad adecuada</strong>: una función, mucho comportamiento oculto — alineado con Ousterhout.</p><hr><h2 id="elasticidad-vs-change-amplification" tabindex="-1">Elasticidad vs Change Amplification <a class="header-anchor" href="#elasticidad-vs-change-amplification" aria-label="Permalink to &quot;Elasticidad vs Change Amplification&quot;">​</a></h2><p>Ousterhout (cap. 1) describe <strong>change amplification</strong>: un cambio pequeño obliga a tocar muchos módulos.</p><h3 id="prueba-de-elasticidad-issue-006-colas-asyncio" tabindex="-1">Prueba de elasticidad: issue <code>#006</code> (colas asyncio) <a class="header-anchor" href="#prueba-de-elasticidad-issue-006-colas-asyncio" aria-label="Permalink to &quot;Prueba de elasticidad: issue `#006` (colas asyncio)&quot;">​</a></h3><p>Refactorizamos <code>run_turn()</code> a workers + <code>asyncio.Queue</code> <strong>sin cambiar</strong>:</p><ul><li>Firma pública <code>run_turn() -&gt; TurnResult | None</code></li><li>Endpoints REST</li><li>Eventos WebSocket (<code>state_change</code>, <code>transcript</code>, <code>response</code>)</li><li>CLI <code>voiceloop --turns N</code></li></ul><p><strong>Veredicto:</strong> la interfaz de <code>VoicePipeline</code> absorbió el cambio interno — <strong>baja amplificación del cambio</strong>.</p><h3 id="prueba-de-estres-issue-007-websocket" tabindex="-1">Prueba de estrés: issue <code>#007</code> WebSocket <a class="header-anchor" href="#prueba-de-estres-issue-007-websocket" aria-label="Permalink to &quot;Prueba de estrés: issue `#007` WebSocket&quot;">​</a></h3><p>Se añadió <code>EventBus</code> + <code>/ws/session</code> sin modificar <code>create_pipeline()</code> — solo suscripción en <code>lifespan</code>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_pipeline.events.subscribe(_broadcast_event)</span></span></code></pre></div><p>La factory no cambió — <strong>buen gusto arquitectónico</strong>: observabilidad como capa orthogonal.</p><h3 id="punto-debil-detectado" tabindex="-1">Punto débil detectado <a class="header-anchor" href="#punto-debil-detectado" aria-label="Permalink to &quot;Punto débil detectado&quot;">​</a></h3><p><code>_create_live_pipeline()</code> creció con <code>if importable</code> por componente. Si el proyecto superara ~10 providers, aparecería <strong>change amplification</strong> en ese único archivo — señal para migrar al Builder (Agente B) en una futura iteración, no ahora.</p><hr><h2 id="comparativa-con-modulos-superficiales-remanentes" tabindex="-1">Comparativa con módulos superficiales remanentes <a class="header-anchor" href="#comparativa-con-modulos-superficiales-remanentes" aria-label="Permalink to &quot;Comparativa con módulos superficiales remanentes&quot;">​</a></h2><p>Aún coexisten re-exports superficiales en <code>stt/__init__.py</code>, <code>tts/__init__.py</code>. Decisión consciente: satisfacer estructura de paquetes Python sin extraer más capas hasta que haya lógica compartida (p. ej. métricas de latencia STT).</p><hr><h2 id="veredicto-final" tabindex="-1">Veredicto final <a class="header-anchor" href="#veredicto-final" aria-label="Permalink to &quot;Veredicto final&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterio</th><th>Evaluación</th></tr></thead><tbody><tr><td>¿La factory fue elástica?</td><td><strong>Sí</strong> — 6 issues post-checkpoint sin editar <code>api.py</code> wiring</td></tr><tr><td>¿Change amplification?</td><td><strong>Baja</strong> en pipeline/API; <strong>moderada</strong> en factory (monolito de registro)</td></tr><tr><td>¿Information hiding?</td><td><strong>Sí</strong> — frontend aislado de proveedores</td></tr><tr><td>¿Velocidad Ralph 2ª mitad?</td><td><strong>Mayor</strong> — seam único documentado en <code>ralph/prompt.md</code></td></tr></tbody></table><h3 id="recomendacion-futura" tabindex="-1">Recomendación futura <a class="header-anchor" href="#recomendacion-futura" aria-label="Permalink to &quot;Recomendación futura&quot;">​</a></h3><p>Si VoiceLoop evoluciona a plugins dinámicos, promover <strong>Agente B (Builder)</strong> manteniendo <code>create_pipeline(&quot;stub&quot;)</code> como atajo. Evitar Registry hasta demostrar necesidad.</p><hr><h2 id="cierre-del-software-journey" tabindex="-1">Cierre del Software Journey <a class="header-anchor" href="#cierre-del-software-journey" aria-label="Permalink to &quot;Cierre del Software Journey&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exploración (grill-me) → Tracer stub → LLM (#003) → Checkpoint (factory)</span></span>\n<span class="line"><span>    → Features paralelos (#002–#009) → E2E → Este sitio</span></span></code></pre></div><p><strong>Repositorio:</strong> <a href="https://github.com/rox651/proyecto-ingenieria-software" target="_blank" rel="noreferrer">https://github.com/rox651/proyecto-ingenieria-software</a><br><strong>Commits:</strong> historial con mensajes <code>feat(#NNN)</code> trazables a issues<br><strong>Tests:</strong> 23/23 passing en CI</p><p>← <a href="/proyecto-ingenieria-software/">Volver al inicio</a></p>',41)])])}const b=a(i,[["render",s]]);export{h as __pageData,b as default};
